struct Resource {};
using UP = std::unique_ptr<Resource>;

UP p1 = std::make_unique<Resource>();
UP p2 = std::make_unique<Resource>();
UP pN; // nullptr

// Core mechanism: Comparison delegates to raw pointer access
// return p1.get() != p2.get();

bool different_objects = (p1 != p2);     // True (different addresses)
bool comparison_to_null = (p1 != nullptr); // True

// Overload for pointer comparison:
// pN is nullptr. (pN.get() != nullptr) is false
bool is_null = (pN != nullptr);         // False
